const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const icons={network:'<circle cx="12" cy="12" r="3"/><circle cx="4" cy="5" r="2"/><circle cx="20" cy="6" r="2"/><circle cx="6" cy="21" r="2"/><path d="m6 7 4 3m4-1 4-2M10 15l-3 4"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',map:'<path d="m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2zM9 3v16M15 5v16"/>',time:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 3"/>',bookmark:'<path d="M6 3h12v19l-6-4-6 4z"/>',access:'<circle cx="12" cy="4" r="2"/><path d="m4 8 8 2 8-2M12 10v6m0 0-5 6m5-6 5 6"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',plus:'<path d="M12 4v16M4 12h16"/>',minus:'<path d="M4 12h16"/>',expand:'<path d="M3 9V3h6m6 0h6v6M3 15v6h6m6 0h6v-6"/>',reset:'<path d="M3 10a9 9 0 1 1 2 8M3 3v7h7"/>',share:'<path d="M12 16V3m-5 5 5-5 5 5M5 12H3v9h18v-9h-2"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',heart:'<path d="M20 4c-3-2-6 0-8 2-2-2-5-4-8-2-6 5 1 12 8 17 7-5 14-12 8-17Z"/>',filter:'<path d="M3 5h18M6 12h12M9 19h6"/>',list:'<path d="M8 5h13M8 12h13M8 19h13M3 5h1M3 12h1M3 19h1"/>',grid:'<rect x="3" y="3" width="7" height="7"/><rect x="14" y="3" width="7" height="7"/><rect x="3" y="14" width="7" height="7"/><rect x="14" y="14" width="7" height="7"/>',check:'<path d="m4 12 5 5L20 6"/>',sound:'<path d="M3 9v6h4l5 4V5L7 9zM16 8q5 4 0 8M19 4q8 8 0 16"/>',external:'<path d="M14 3h7v7m0-7L10 14M10 3H3v18h18v-7"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>'};
const icon=n=>`<span class="icon" aria-hidden="true"><svg viewBox="0 0 24 24">${icons[n]||icons.network}</svg></span>`;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let params=new URLSearchParams(location.search),lang=params.get('lang')||'de',saved=[];try{saved=JSON.parse(localStorage.getItem('oc-saved')||'[]')}catch{}saved=saved.filter(id=>OBJECTS.some(o=>o.id===id));
const T=(de,en,easy)=>lang==='en'?en:lang==='easy'?(easy||de):de;
let view=params.get('view')||'network',netTheme=params.get('theme')||'all',netZoom=1;
const THEMES=[{id:'bildwelten',title:'Glaube wird Bild',en:'Faith in pictures',museum:'St.-Annen-Museum',image:0,ids:[0,4,3],tag:'Glaube',intro:'Altäre verbinden Malerei, Erzählung und den Raum, für den sie entstanden sind. Entdecken Sie Bildwelten zwischen dem späten Mittelalter und dem frühen 19. Jahrhundert.'},{id:'menschen',title:'Ein Blick auf uns',en:'A look at ourselves',museum:'Museum Behnhaus Drägerhaus',image:1,ids:[1,2,9],tag:'Porträt',intro:'Ein Porträt bewahrt einen Blick und zeigt zugleich, wie Menschen gesehen werden wollten. Drei Werke eröffnen unterschiedliche Perspektiven auf Selbstbild und Familie.'},{id:'hansestadt',title:'Eine Stadt, die verbindet',en:'A city that connects',museum:'Museum Holstentor',image:7,ids:[6,7],tag:'Hanse',intro:'Lübeck lässt sich als Stadt des Austauschs entdecken. Architektur- und Schiffsmodelle bringen Stadtgeschichte und maritime Verbindungen zusammen.'},{id:'natur',title:'Die Welt vor unserer Tür',en:'The world on our doorstep',museum:'Museum für Natur und Umwelt',image:5,ids:[5,8],tag:'Natur',intro:'Vom Material aus dem Weltall bis zum Modell der heimischen Landschaft: Natur lässt sich in sehr unterschiedlichen Maßstäben erkunden.'}];
function url(page='explore',extra={}){const p=new URLSearchParams({page,lang,...extra});return '?'+p}
function go(page='explore',extra={}){history.pushState({},'',url(page,extra));params=new URLSearchParams(location.search);view=params.get('view')||'network';netTheme=params.get('theme')||'all';render();window.scrollTo(0,0)}
function chrome(){document.documentElement.lang=lang==='en'?'en':'de';$('#header').innerHTML=`<div class="topline"><span>${T('LÜBECKER MUSEEN · KULTUR VERBINDET','LÜBECK MUSEUMS · CULTURE CONNECTS')}</span><button data-action="about">${T('Interaktiver Prototyp · Beispieldaten','Interactive prototype · Sample data','Diese Internet-Seite ist ein Beispiel')}</button><span>${T('KUNST. GESCHICHTE. NATUR.','ART. HISTORY. NATURE.')}</span></div><div class="header wrap"><a class="brand" href="${url()}" aria-label="Online Collection Startseite"><span class="brandmark" aria-hidden="true">LM</span><span class="brandtext">LÜBECKER<br>MUSEEN<small>ONLINE COLLECTION</small></span></a><nav class="mainnav" aria-label="${T('Hauptnavigation','Main navigation')}"><a class="navlink ${!params.get('page')||params.get('page')==='explore'?'active':''}" href="${url()}">${T('Entdecken','Explore','Bilder entdecken')}</a><a class="navlink ${params.get('page')==='search'?'active':''}" href="${url('search')}">${T('Sammlung','Collection','Objekte suchen')}</a><a class="navlink ${params.get('page')==='stories'?'active':''}" href="${url('stories')}">${T('Themen & Geschichten','Stories','Geschichten')}</a><a class="navlink ${params.get('page')==='saved'?'active':''}" href="${url('saved')}">${T('Meine Merkliste','Saved objects','Meine Bilder')} <span class="count">${saved.length}</span></a></nav><div class="header-tools"><select class="language" aria-label="${T('Sprache wählen','Choose language')}" id="language"><option value="de" ${lang==='de'?'selected':''}>DE</option><option value="en" ${lang==='en'?'selected':''}>EN</option><option value="easy" ${lang==='easy'?'selected':''}>Leichte Sprache</option></select><button class="iconbutton" data-action="access" aria-label="${T('Darstellung anpassen','Display settings')}">${icon('access')}</button></div></div>`;$('#footer').innerHTML=`<div class="footer wrap"><div>© ${new Date().getFullYear()} ${T('Lübecker Museen · Gestaltungsvorschlag','Lübeck Museums · Design proposal')}<br>${T('Recherchebeispiele · kein Live-Sammlungsbestand','Research examples · not a live collection')}</div><div class="footer-links"><button data-action="sources">${T('Bildnachweise','Image credits')}</button><button data-action="access">${T('Barrierefreiheit','Accessibility')}</button><button data-action="privacy">${T('Datenschutz & Kontakt','Privacy & contact')}</button><a href="${url('editor')}">${T('Redaktion · Demo','Editorial · Demo')}</a><button data-action="about">${T('Zum Prototyp','About this prototype')}</button></div></div>`}
function objectImage(o,cls=''){return `<img class="${cls}" src="${esc(o.imageUrl)}" alt="${esc(o.alt)}" loading="lazy" referrerpolicy="no-referrer">`}
function themeCards(){return `<div class="story-grid">${THEMES.map(t=>`<button class="story-card" data-story="${t.id}"><figure>${objectImage(OBJECTS[t.image])}</figure><div class="body"><small>${esc(t.museum)}</small><h3>${lang==='en'?t.en:t.title}</h3><div class="meta">${t.ids.length} ${T('Objekte','objects')} · ${T('Eine Geschichte entdecken','Discover a story')}</div></div></button>`).join('')}</div>`}
function network(){const positions=[[48,48,'hero',1],[23,37,'medium',0],[73,28,'medium',2],[83,69,'small',5],[17,77,'small',7],[60,84,'small',9]];let subset=netTheme==='all'?null:THEMES.find(t=>t.id===netTheme);const selected=subset?subset.ids.map(i=>OBJECTS[i]):null;return `<div class="network"><div class="network-head"><p class="eyebrow">${T('DIE SAMMLUNG IN VERBINDUNG','THE COLLECTION, CONNECTED')}</p><strong>${subset?(lang==='en'?subset.en:subset.title):T('Jedes Objekt öffnet eine neue Welt.','Every object opens a new world.','Jedes Bild erzählt eine Geschichte.')}</strong></div><div class="network-helper">${icon('network')}${T('Objekte anklicken · Zusammenhänge entdecken','Select an object · Discover connections')}</div><div class="net-canvas" id="netcanvas"><svg class="net-lines" viewBox="0 0 1000 460" preserveAspectRatio="none" aria-hidden="true"><path d="M230 170Q340 40 480 220M230 170Q80 240 170 355M170 355Q430 390 480 220M480 220Q650 380 830 317M480 220Q580 60 730 129M730 129Q830 210 830 317M480 220Q540 370 600 385"/><path class="person" d="M480 220Q350 180 405 65M405 65Q580 15 730 129M600 385Q680 280 730 129"/><path class="place" d="M170 355Q400 420 300 305M300 305Q600 420 830 317M230 170Q580 100 670 265M670 265Q760 320 830 317"/></svg>${positions.map(([x,y,s,i],n)=>{const o=selected?selected[n%selected.length]:OBJECTS[i];if(selected&&n>=selected.length)return '';return `<button class="netnode ${s}" style="left:${x}%;top:${y}%" data-object="${o.id}" aria-label="${esc(o.title)} ${T('öffnen','open')}">${objectImage(o)}<span>${esc(o.title)}</span></button>`}).join('')}<button class="topic-node" style="left:12%;top:14%" data-story="bildwelten">${T('Glaube & Bildwelten','Faith & imagery')}</button><button class="topic-node person" style="left:40.5%;top:14%" data-filter="person" data-value="Johann Friedrich Overbeck">Friedrich Overbeck</button><button class="topic-node place" style="left:30%;top:66%" data-filter="tag" data-value="Lübeck">Lübeck</button><button class="topic-node" style="left:67%;top:57%" data-story="menschen">${T('Menschen & Geschichten','People & stories')}</button></div><div class="net-caption"><span class="legend"><i></i>${T('Thema','Theme')}</span><span class="legend"><i class="blue"></i>${T('Person','Person')}</span><span class="legend"><i class="orange"></i>${T('Ortsbezug','Place reference')}</span></div><div class="net-controls"><button data-action="net-minus" aria-label="${T('Netz verkleinern','Zoom out')}">${icon('minus')}</button><button data-action="net-plus" aria-label="${T('Netz vergrößern','Zoom in')}">${icon('plus')}</button><button data-action="net-reset" aria-label="${T('Netz zurücksetzen','Reset network')}">${icon('reset')}</button><button data-action="net-list" aria-label="${T('Beziehungen als Liste','Relationships as list')}">${icon('list')}</button></div></div><div class="explore-bottom"><span>${OBJECTS.length} ${T('recherchierte Objekte','researched objects')} · 4 ${T('Häuser','museums')} · ${T('Verbindungen exemplarisch kuratiert','illustrative curated connections')}</span><button class="textbutton" data-action="surprise">${icon('network')}${T('Überrasch mich','Surprise me','Zeige mir ein Bild')}</button></div>`}
function explore(){return `<div class="wrap"><section class="intro"><div><div class="eyebrow">${T('EIN KOSMOS AUS KUNST, GESCHICHTE UND NATUR','A WORLD OF ART, HISTORY AND NATURE')}</div><h1>${T('Neugier kennt<br><em>keine Museumsmauern.</em>','Curiosity goes<br><em>beyond museum walls.</em>','Entdecke Bilder.<br><em>Und ihre Geschichten.</em>')}</h1></div><p class="intro-copy">${T('Folgen Sie Ihrer Neugier. Entdecken Sie Objekte und überraschende Verbindungen zwischen den Lübecker Sammlungen.','Follow your curiosity. Discover objects and unexpected connections across Lübeck’s collections.','Klicke auf ein Bild. Du erfährst mehr über das Bild. Du kannst auch nach Objekten suchen.')}</p></section><div class="toolbar"><div class="views" aria-label="${T('Ansicht wählen','Choose view')}">${[['network','network','Sammlungsnetz','Network'],['search','search','Suche','Search'],['map','map','Karte','Map'],['time','time','Zeitreise','Timeline']].map(([v,i,de,en])=>`<button data-view="${v}" class="${view===v?'active':''}" aria-pressed="${view===v}">${icon(i)}${T(de,en)}</button>`).join('')}</div><div class="chip-row"><button class="chip ${netTheme==='all'?'active':''}" data-theme="all">${T('Alle Verbindungen','All connections')}</button>${THEMES.slice(0,2).map(t=>`<button class="chip ${netTheme===t.id?'active':''}" data-theme="${t.id}">${lang==='en'?t.en:t.title}</button>`).join('')}</div></div><div id="exploration">${view==='map'?mapView():view==='time'?timeView():network()}</div><section class="section"><div class="section-head"><div><div class="eyebrow">${T('KURATIERTE PERSPEKTIVEN','CURATED PERSPECTIVES')}</div><h2>${T('Eine Sammlung. Viele Geschichten.','One collection. Many stories.','Geschichten aus dem Museum')}</h2></div><a class="textbutton" href="${url('stories')}">${T('Alle Themen entdecken','Explore all stories')}</a></div>${themeCards()}</section></div>`}
function render(){chrome();const page=params.get('page')||'explore';$('#main').innerHTML=page==='explore'?explore():page==='search'?searchPage():page==='object'?objectPage():page==='stories'?storiesPage():page==='story'?storyPage():page==='saved'?savedPage():page==='editor'?editorPage():explore();document.title=(page==='object'?(OBJECTS.find(o=>o.id===params.get('id'))?.title||'Objekt')+' · ':'')+'Online Collection · Lübecker Museen';}
document.addEventListener('click',e=>{const a=e.target.closest('a');if(a?.getAttribute('href')?.startsWith('?')&&!e.metaKey&&!e.ctrlKey){e.preventDefault();const u=new URL(a.href);history.pushState({},'',u.search);params=new URLSearchParams(u.search);view=params.get('view')||'network';netTheme=params.get('theme')||'all';render();window.scrollTo(0,0);return}const b=e.target.closest('button');if(!b)return;if(b.dataset.object){go('object',{id:b.dataset.object});return}if(b.dataset.story){go('story',{id:b.dataset.story});return}if(b.dataset.view){if(b.dataset.view==='search')go('search');else go('explore',{view:b.dataset.view});return}if(b.dataset.theme){go('explore',{theme:b.dataset.theme,view:'network'});return}if(b.dataset.filter){go('search',{[b.dataset.filter]:b.dataset.value});return}if(b.dataset.action)action(b.dataset.action,b)});
document.addEventListener('change',e=>{if(e.target.id==='language'){lang=e.target.value;params.set('lang',lang);history.replaceState({},'','?'+params);render()}});
window.addEventListener('popstate',()=>{params=new URLSearchParams(location.search);lang=params.get('lang')||'de';view=params.get('view')||'network';netTheme=params.get('theme')||'all';render()});
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function modal(title,body){const m=$('#modal');m.className='';m.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="iconbutton" data-action="close" aria-label="${T('Schließen','Close')}">${icon('close')}</button></div><div class="modal-body">${body}</div>`;m.showModal()}
function action(a,b){if(a==='close')$('#modal').close();else if(a==='surprise')go('object',{id:OBJECTS[Math.floor(Math.random()*OBJECTS.length)].id});else if(a.startsWith('net-')){if(a==='net-list'){modal(T('Verbindungen im Sammlungsnetz','Network relationships'),`<p>${T('Exemplarische Beziehungen des Prototyps:','Illustrative prototype relationships:')}</p><div class="network-list">${OBJECTS.map(o=>`<button class="chip" data-object="${o.id}">${esc(o.title)} · ${esc(o.tags.join(', '))}</button>`).join('')}</div>`);return}netZoom=a==='net-reset'?1:Math.max(.65,Math.min(1.5,netZoom+(a==='net-plus'?.1:-.1)));$('#netcanvas').style.transform=`scale(${netZoom*(innerWidth<760?.8:1)})`}else actionFull(a,b)}
const facets=[['museum','Museum','Museum'],['collection','Sammlung','Collection'],['type','Objektbezeichnung','Object type'],['material','Material','Material'],['technique','Technik','Technique'],['date','Datierung','Date'],['place','Herstellungs- / Fundort','Place of creation / discovery'],['person','Person','Person'],['tag','Schlagwort','Keyword']];
function filtered(){let list=OBJECTS.filter(o=>{const q=(params.get('q')||'').toLocaleLowerCase();if(q&&!`${o.title} ${o.person} ${o.museum} ${o.description} ${o.tags.join(' ')}`.toLocaleLowerCase().includes(q))return false;return facets.every(([k])=>!params.get(k)||(k==='tag'?o.tags.includes(params.get(k)):o[k]===params.get(k)))});const sort=params.get('sort')||'relevance';if(sort==='old')list.sort((a,b)=>(a.year||9999)-(b.year||9999));if(sort==='new')list.sort((a,b)=>(b.year||0)-(a.year||0));if(sort==='title')list.sort((a,b)=>a.title.localeCompare(b.title));return list}
function card(o){return `<article class="object-card"><a href="${url('object',{id:o.id})}"><figure>${objectImage(o)}</figure><div><h3 lang="de">${esc(o.title)}</h3><p>${esc(o.creator||o.type)} · ${esc(o.date)}</p><p>${esc(o.museum)}</p></div></a><button class="iconbutton save ${saved.includes(o.id)?'saved':''}" data-action="save" data-id="${o.id}" aria-label="${T('Merken: ','Save: ')+esc(o.title)}" aria-pressed="${saved.includes(o.id)}">${icon('bookmark')}</button></article>`}
function crumbs(label){return `<div class="breadcrumb"><a href="${url()}">${T('Entdecken','Explore')}</a><span>/</span><span>${label}</span></div>`}
function searchPage(){let list=filtered(),active=facets.filter(([k])=>params.get(k));return `<div class="wrap">${crumbs(T('Sammlung','Collection'))}<div class="intro" style="padding-top:0"><div><div class="eyebrow">${T('DIE SAMMLUNG ERFORSCHEN','EXPLORE THE COLLECTION')}</div><h1>${T('Was weckt Ihre Neugier?','What sparks your curiosity?','Was möchtest du finden?')}</h1></div><p class="intro-copy">${T('Kunst, Geschichte und Natur – über Museumsgrenzen hinweg.','Art, history and nature – across museum boundaries.')}</p></div><form class="searchbar" id="search-form" role="search">${icon('search')}<input id="query" name="q" list="suggestions" autocomplete="off" value="${esc(params.get('q')||'')}" aria-label="${T('Sammlung durchsuchen','Search collection')}" placeholder="${T('Objekt, Person oder Thema suchen …','Search objects, people or themes …')}"><datalist id="suggestions">${[...new Set(OBJECTS.flatMap(o=>[o.title,o.person,...o.tags]))].map(s=>`<option value="${esc(s)}">`).join('')}</datalist><button class="primary">${T('Suchen','Search')}</button></form><div class="search-layout"><aside class="filters" id="filters" aria-label="${T('Suchfilter','Search filters')}"><div class="filter"><strong>${T('Suche verfeinern','Refine search')}</strong></div>${facets.map(([k,de,en])=>`<div class="filter"><label for="filter-${k}">${T(de,en)}</label><select id="filter-${k}" data-facet="${k}"><option value="">${T('Alle','All')}</option>${[...new Set(OBJECTS.flatMap(o=>k==='tag'?o.tags:[o[k]]))].sort().map(v=>`<option value="${esc(v)}" ${params.get(k)===v?'selected':''}>${esc(v)}</option>`).join('')}</select></div>`).join('')}<button class="textbutton" style="margin-top:20px" data-action="reset-search">${T('Alle Filter zurücksetzen','Reset all filters')}</button></aside><section id="results" class="${params.get('layout')==='list'?'search-list':''}"><div class="results-head"><strong aria-live="polite">${list.length} ${T('Objekte','objects')}</strong><button class="secondary mobile-only" data-action="filters">${icon('filter')}${T('Filter','Filters')}</button><div class="button-row"><select id="sort" aria-label="${T('Sortierung','Sort order')}">${[['relevance','Relevanz','Relevance'],['old','Älteste zuerst','Oldest first'],['new','Neueste zuerst','Newest first'],['title','Titel A–Z','Title A–Z']].map(([v,de,en])=>`<option value="${v}" ${params.get('sort')===v?'selected':''}>${T(de,en)}</option>`).join('')}</select><button class="iconbutton" data-action="layout" aria-label="${T('Raster oder Liste umschalten','Toggle grid or list')}">${icon(params.get('layout')==='list'?'grid':'list')}</button><button class="iconbutton" data-action="share" aria-label="${T('Suchlink teilen','Share search')}">${icon('share')}</button></div></div>${active.length?`<div class="chip-row" style="margin-bottom:20px">${active.map(([k])=>`<button class="chip" data-action="remove-filter" data-key="${k}">${esc(params.get(k))} ×</button>`).join('')}</div>`:''}<div class="object-grid">${list.length?list.map(card).join(''):`<div class="empty"><h2>${T('Keine passenden Objekte','No matching objects')}</h2><p>${T('Versuchen Sie einen anderen Begriff oder weniger Filter.','Try another search term or fewer filters.')}</p><button class="primary" data-action="reset-search">${T('Suche zurücksetzen','Reset search')}</button></div>`}</div><p class="fieldnote">${T('10 recherchierte Beispiele aus 4 Häusern. Fehlende Metadaten sind als „Nicht belegt“ gekennzeichnet.','10 researched examples from 4 museums. Missing metadata is marked “Nicht belegt”.')}</p></section></div></div>`}
let detailTab='overview';
function currentObject(){return OBJECTS.find(o=>o.id===params.get('id'))||OBJECTS[1]}
function objectPage(){const o=currentObject();return `<div class="wrap">${crumbs(`<a href="${url('search')}">${T('Sammlung','Collection')}</a> / ${esc(o.title)}`)}<div class="detail"><div><div class="viewer" id="object-viewer">${objectImage(o)}<div class="controls"><button class="iconbutton" data-action="zoom" aria-label="${T('Bild vergrößern','Enlarge image')}">${icon('plus')}</button><button class="iconbutton" data-action="zoom" aria-label="${T('Bild im Vollbild ansehen','Open fullscreen viewer')}">${icon('expand')}</button></div></div><div class="image-credit">${esc(o.credit)} · ${esc(o.license)}<br>${T('Web-Abbildung · für den Prototyp skaliert','Web image · resized for this prototype')}</div><button class="textbutton" data-action="image-description">${icon('access')}${T('Bildbeschreibung lesen','Read image description')}</button></div><section><div class="eyebrow">${esc(o.museum)}</div><h1 lang="de">${esc(o.title)}</h1><p class="artist">${esc(o.creator||T('Urheberschaft nicht belegt','Creator not documented'))} · ${esc(o.date)}</p><div class="chip-row">${o.tags.map(t=>`<button class="chip" data-filter="tag" data-value="${esc(t)}">${esc(t)}</button>`).join('')}</div><p class="description" lang="de">${esc(lang==='easy'?o.easy:o.description)}</p>${lang==='en'?`<p class="subtle">Object text available in German; source metadata retained.</p>`:''}<dl><dt>${T('Objektart','Object type')}</dt><dd>${esc(o.type)}</dd><dt>${T('Material / Technik','Material / technique')}</dt><dd>${esc(o.medium||T('Nicht belegt','Not documented'))}</dd><dt>${T('Sammlung','Collection')}</dt><dd>${esc(o.collection)}</dd><dt>${T('Nutzungsrechte','Usage rights')}</dt><dd><a href="${esc(o.licenseUrl)}" target="_blank" rel="noopener">${esc(o.license)}</a></dd></dl><div class="button-row"><button class="primary ${saved.includes(o.id)?'saved':''}" data-action="save" data-id="${o.id}" aria-pressed="${saved.includes(o.id)}">${icon('bookmark')}${saved.includes(o.id)?T('Gemerkt','Saved'):T('Objekt merken','Save object')}</button><button class="secondary" data-action="share">${icon('share')}${T('Teilen','Share')}</button><button class="iconbutton" data-action="like" aria-label="${T('Gefällt mir – lokale Demo','Like – local demo')}" aria-pressed="false">${icon('heart')}</button></div><p class="fieldnote">${T('Quellenbeleg aus Wikimedia Commons. Keine Inventarnummer und kein aktueller Ausstellungsstatus übermittelt.','Source record from Wikimedia Commons. No inventory number or current exhibition status supplied.')}</p></section></div><div class="tabs" role="tablist" aria-label="${T('Objektdetails','Object details')}">${[['overview','Objekt & Herkunft','Object & provenance'],['relations','Verbindungen','Connections'],['media','Medien & Nutzung','Media & reuse'],['guide','Hören & Verstehen','Listen & understand']].map(([v,de,en])=>`<button role="tab" aria-selected="${detailTab===v}" class="${detailTab===v?'active':''}" data-action="detail-tab" data-tab="${v}">${T(de,en)}</button>`).join('')}</div><div id="detail-content">${detailContent(o)}</div><section class="section"><div class="section-head"><div><div class="eyebrow">${T('WEITERENTDECKEN','KEEP EXPLORING')}</div><h2>${T('Verbunden durch','Connected by')} „${esc(o.tags[0])}“</h2></div><button class="textbutton" data-filter="tag" data-value="${esc(o.tags[0])}">${T('Alle Verbindungen','All connections')}</button></div><div class="object-grid">${OBJECTS.filter(x=>x.id!==o.id&&x.tags.includes(o.tags[0])).slice(0,3).map(card).join('')}</div></section></div>`}
function detailContent(o){if(detailTab==='relations')return `<div class="callout"><h3>${T('Warum sind diese Objekte verbunden?','Why are these objects connected?')}</h3><p>${T('Die Verbindungen sind für diesen Prototyp kuratiert. Person, Sammlung und gemeinsame Themen bilden eigenständige Beziehungen.','These connections were curated for the prototype. People, collections and common themes define distinct relationships.')}</p><div class="network-list">${OBJECTS.filter(x=>x.id!==o.id).map(x=>{let why=x.person===o.person&&o.creator?T('Gleiche Person','Same person')+': '+o.person:x.museum===o.museum?T('Gleiches Museum','Same museum'):x.tags.find(t=>o.tags.includes(t))?T('Gemeinsames Thema','Shared theme')+': '+x.tags.find(t=>o.tags.includes(t)):null;return why?`<button class="chip" data-object="${x.id}">${esc(x.title)}<br>${esc(why)}</button>`:''}).join('')}</div><div class="button-row" style="margin-top:25px"><a class="secondary" href="${url('explore')}">${icon('network')}${T('Zum Sammlungsnetz','Open collection network')}</a><button class="secondary" data-action="older">${T('Älteres Objekt','Older object')}</button><button class="secondary" data-action="younger">${T('Jüngeres Objekt','Newer object')}</button></div></div>`;if(detailTab==='media')return `<div class="metadata"><div class="callout"><h3>${T('Dieses Bild weiterverwenden','Reuse this image')}</h3><p>${esc(o.credit)} · ${esc(o.license)}</p><p>${T('Bitte beachten Sie den Quellenbeleg und die Lizenzbedingungen. Die lokale Datei ist ein verkleinertes Web-Derivat.','Please check the source and licence terms. The local file is a resized web derivative.')}</p><div class="button-row"><a class="primary" href="${esc(o.imageUrl)}" download="${o.id}.jpg">${icon('download')}${T('Web-Bild herunterladen','Download web image')}</a><button class="secondary" data-action="request">${T('HQ / TIFF anfragen','Request HQ / TIFF')}</button></div></div><div class="callout"><h3>${T('Quellen und Nachnutzung','Sources and reuse')}</h3><p>${T('Digitalisat und Rechteangaben stammen aus der verlinkten Commons-Dateiseite. Eine Daphne- oder IIIF-Anbindung ist hier nicht aktiv.','Image and licence information come from the linked Commons file page. Daphne and IIIF are not connected in this prototype.')}</p><a href="${esc(o.sourceUrl)}" target="_blank" rel="noopener">${T('Original und Lizenznachweis öffnen','Open original and licence record')}</a><p style="margin-top:15px"><a href="${esc(o.licenseUrl)}" target="_blank" rel="noopener">${esc(o.license)}</a></p></div></div>`;if(detailTab==='guide')return `<div class="metadata"><div class="callout"><h3>${T('Das Objekt kennenlernen','Get to know the object')}</h3><p>${T('Hörbeispiel als Browser-Vorlesefunktion. Ein professioneller eGuide ist noch nicht angebunden.','Audio demonstration using browser speech. A professional eGuide is not connected.')}</p><div class="button-row"><button class="primary" data-action="speak">${icon('sound')}${T('Text vorlesen','Read text aloud')}</button><button class="secondary" data-action="stop-speak">${T('Stoppen','Stop')}</button></div><details style="margin-top:20px"><summary>${T('Transkript lesen','Read transcript')}</summary><p lang="de" style="margin-top:15px">${esc(o.description)}</p></details></div><div class="callout"><h3>${T('Einfach erklärt','Simply explained')}</h3><p lang="de">${esc(o.easy)}</p><p class="hint">${T('Textentwurf in einfacher Sprache; Prüfung durch eine Leichte-Sprache-Prüfgruppe steht aus.','Draft in simple German; review by an easy-language group is pending.')}</p></div></div>`;return `<div class="metadata"><div><h3>${T('Was wir über das Objekt wissen','What we know about this object')}</h3>${[[T('Quellen-ID des Prototyps','Prototype source ID'),o.id],[T('Person','Person'),o.person],[T('Datierung','Date'),o.date],[T('Material','Material'),o.material],[T('Technik','Technique'),o.technique],[T('Herstellungs- / Fundort','Place of creation / discovery'),o.place],[T('Provenienzstatus','Provenance status'),T('Nicht übermittelt','Not supplied')]].map(([k,v])=>`<div class="pair"><span>${k}</span><span>${esc(v)}</span></div>`).join('')}<p class="fieldnote">${T('Die Quellen-ID ist keine Inventarnummer. Leerfelder des späteren Daphne-Exports werden in der Produktivfassung ausgeblendet.','The source ID is not an inventory number. Empty Daphne fields will be omitted in the production version.')}</p></div><div><div class="callout"><h3>${T('Wissen wächst im Austausch.','Knowledge grows through exchange.')}</h3><p>${T('Sie erkennen ein Detail oder haben eine Frage zu diesem Objekt? Teilen Sie Ihr Wissen mit dem Museum.','Recognise a detail or have a question about this object? Share your knowledge with the museum.')}</p><button class="secondary" data-action="knowledge">${icon('mail')}${T('Wissen teilen','Share knowledge')}</button></div><div class="notice">${T('Recherchebeispiel: Objektdaten, Rechte und Provenienz müssen vor einer echten Veröffentlichung durch das Museum geprüft werden.','Research example: object data, rights and provenance require museum review before production publication.')}</div><a href="${esc(o.sourceUrl)}" target="_blank" rel="noopener" class="textbutton">${T('Quellenbeleg ansehen','View source record')}${icon('external')}</a></div></div>`}
function storiesPage(){return `<div class="wrap">${crumbs(T('Themen & Geschichten','Stories'))}<div class="intro"><div><div class="eyebrow">${T('NEUE PERSPEKTIVEN AUF DIE SAMMLUNG','NEW PERSPECTIVES ON THE COLLECTION')}</div><h1>${T('Geschichten, die verbinden.','Stories that connect.','Geschichten aus den Museen')}</h1></div><p class="intro-copy">${T('Vier beispielhafte Rundgänge. Viele Möglichkeiten, die Sammlung zu entdecken.','Four illustrative journeys. Many ways to discover the collection.')}</p></div>${themeCards()}<div class="notice">${T('Redaktionelle Themenentwürfe für den Clickdummy. Die verbindlichen Museumstexte und Objektlisten liegen noch nicht vor.','Editorial story drafts for this prototype. Approved museum texts and object lists have not yet been supplied.')}</div></div>`}
function storyPage(){const t=THEMES.find(x=>x.id===params.get('id'))||THEMES[0];return `<div class="wrap">${crumbs(T('Themen & Geschichten','Stories'))}<section class="story-hero"><div class="copy"><div class="eyebrow">${esc(t.museum)}</div><h1>${lang==='en'?t.en:t.title}</h1><p lang="de">${esc(t.intro)}</p><div style="margin-top:25px">${t.ids.length} ${T('Objekte · kuratierter Themenentwurf','objects · curated story draft')}</div></div>${objectImage(OBJECTS[t.image])}</section>${t.ids.map((idx,i)=>{const o=OBJECTS[idx];return `<section class="chapter"><span class="num">0${i+1}</span><div><div class="eyebrow">${esc(o.date)}</div><h2 lang="de">${esc(o.title)}</h2><p lang="de">${esc(lang==='easy'?o.easy:o.description)}</p><a class="secondary" href="${url('object',{id:o.id})}">${T('Objekt entdecken','Explore object')}</a></div><a href="${url('object',{id:o.id})}" aria-label="${esc(o.title)}">${objectImage(o)}</a></section>`}).join('')}<div class="button-row" style="margin-top:30px"><a class="primary" href="${url('explore',{theme:t.id})}">${icon('network')}${T('Dieses Thema im Netz ansehen','See this theme in the network')}</a><button class="secondary" data-action="save-story" data-id="${t.id}">${icon('bookmark')}${T('Alle Objekte merken','Save all objects')}</button><button class="secondary" data-action="share">${icon('share')}${T('Geschichte teilen','Share story')}</button></div></div>`}
function savedPage(){const shared=params.get('ids');const ids=shared?shared.split(','):saved;const list=OBJECTS.filter(o=>ids.includes(o.id));return `<div class="wrap">${crumbs(T('Meine Merkliste','Saved objects'))}<div class="intro"><div><div class="eyebrow">${T('IHR PERSÖNLICHER BLICK AUF DIE SAMMLUNG','YOUR PERSONAL VIEW OF THE COLLECTION')}</div><h1>${shared?T('Eine geteilte Entdeckung.','A shared discovery.'):T('Was bleibt, ist Neugier.','Curiosity stays with us.','Deine gemerkten Bilder')}</h1></div><p class="intro-copy">${T('Ohne Anmeldung. Ihre Merkliste wird nur in diesem Browser gespeichert.','No account needed. Your saved objects stay in this browser.')}</p></div><div class="toolbar"><strong>${list.length} ${T('gemerkte Objekte','saved objects')}</strong><div class="button-row">${shared?`<button class="secondary" data-action="import-saved">${T('In meine Merkliste übernehmen','Add to my saved objects')}</button>`:''}<button class="secondary" data-action="share-saved" ${!list.length?'disabled':''}>${icon('share')}${T('Merkliste teilen','Share list')}</button><button class="secondary" data-action="csv" ${!list.length?'disabled':''}>${icon('download')}CSV</button><button class="secondary" data-action="print" ${!list.length?'disabled':''}>${icon('download')}${T('Drucken / PDF','Print / PDF')}</button></div></div><div class="object-grid">${list.length?list.map(card).join(''):`<div class="empty"><h2>${T('Hier ist Platz für Ihre Entdeckungen.','Make room for your discoveries.')}</h2><p>${T('Merken Sie Objekte mit dem Lesezeichen. Sie finden sie anschließend hier wieder.','Use the bookmark button on an object to save it here.')}</p><a class="primary" href="${url('search')}">${T('Sammlung entdecken','Explore collection')}</a></div>`}</div></div>`}
const MUSEUMS=[{name:'Museum Behnhaus Drägerhaus',x:62,y:22,idx:1},{name:'St.-Annen-Museum',x:62,y:62,idx:0},{name:'Museum Holstentor',x:25,y:53,idx:7},{name:'Museum für Natur und Umwelt',x:50,y:78,idx:5}];let mapSelected='';
function mapView(){return `<div class="map-layout"><div class="map"><svg viewBox="0 0 650 520" role="img" aria-label="${T('Schematische Karte der Lübecker Altstadt, keine exakte Navigation','Schematic map of Lübeck old town, not for navigation')}"><rect width="650" height="520" fill="#e4e9df"/><path d="M260-40C130 80 110 240 185 370S270 560 430 560M450-40C570 70 560 200 515 330S490 540 410 560" fill="none" stroke="#a7c6ce" stroke-width="45"/><path d="M270-40C150 70 140 230 210 365S290 530 410 555M450-30C545 70 535 210 495 330S470 520 420 550" fill="none" stroke="#c6dbe0" stroke-width="10"/><g stroke="#fcfcf7" stroke-width="12" fill="none"><path d="M290 20 310 460M385 20 410 480M205 135 503 130M178 235 520 230M211 325 495 320M275 402 470 400M170 240 40 260M430 130 600 110"/></g><g fill="#d1d9ca"><rect x="325" y="150" width="60" height="66" rx="7"/><rect x="235" y="253" width="58" height="55" rx="7"/><rect x="330" y="342" width="63" height="50" rx="7"/></g><text x="290" y="287" fill="#6d7e74" font-size="18" letter-spacing="5">ALTSTADT</text><text x="72" y="350" fill="#527b87" font-size="14" transform="rotate(-70 72 350)">TRAVE</text><text x="563" y="306" fill="#527b87" font-size="14" transform="rotate(75 563 306)">ELBE-LÜBECK-KANAL</text></svg>${MUSEUMS.map((m,i)=>`<button class="map-pin ${mapSelected===m.name?'active':''}" style="left:${m.x}%;top:${m.y}%" data-action="map-select" data-id="${m.name}" aria-label="${esc(m.name)}">${i+1} · ${i===0?'Behnhaus':i===1?'St. Annen':i===2?'Holstentor':T('Natur & Umwelt','Nature')}</button>`).join('')}<div class="map-label">${T('Schematische Museumskarte · Option A-29','Schematic museum map · Option A-29')}</div></div><div class="map-list"><div class="eyebrow" style="margin-top:8px">${T('VIER HÄUSER ENTDECKEN','DISCOVER FOUR MUSEUMS')}</div>${MUSEUMS.map((m,i)=>`<button class="museum-row ${mapSelected===m.name?'active':''}" data-action="map-select" data-id="${esc(m.name)}">${objectImage(OBJECTS[m.idx])}<span><strong>${esc(m.name)}</strong><small>${OBJECTS.filter(o=>o.museum===m.name).length} ${T('Beispielobjekte','sample objects')}</small></span></button>`).join('')}${mapSelected?`<a class="primary" href="${url('search',{museum:mapSelected})}">${T('Objekte dieses Hauses anzeigen','Show this museum’s objects')}</a>`:`<p class="subtle">${T('Wählen Sie einen Standort. Die Karte zeigt Museumsstandorte, keine Herstellungs- oder Fundorte.','Choose a museum. This map shows museum locations, not object origins or discovery sites.')}</p>`}</div></div>`}
function timeView(){return `<div class="callout"><div class="section-head"><div><div class="eyebrow">${T('EINE REISE DURCH DIE ZEIT','A JOURNEY THROUGH TIME')}</div><h2>1491 — 1830</h2></div><span class="prototype-tag">${T('Option A-30','Option A-30')}</span></div><p>${T('Von spätmittelalterlichen Bildwelten zu Menschenbildern des 19. Jahrhunderts. Nur Objekte mit belegter Datierung werden eingeordnet.','From late medieval imagery to 19th-century portraits. Only objects with documented dates are shown.')}</p><div class="timeline">${OBJECTS.filter(o=>o.year).sort((a,b)=>a.year-b.year).map(o=>`<article class="timeitem"><div class="year">${esc(o.date)}</div><a href="${url('object',{id:o.id})}">${objectImage(o)}<h3>${esc(o.title)}</h3></a><p>${esc(o.creator)}</p></article>`).join('')}</div></div>`}
let editorTab='review',reviewState={},reviewLog=[];
function editorPage(){return `<div class="wrap">${crumbs(T('Redaktion','Editorial'))}<div class="intro"><div><div class="eyebrow">${T('REDAKTIONSSCHICHT','EDITORIAL WORKSPACE')}</div><h1>${T('Prüfen. Einordnen. Freigeben.','Review. Contextualise. Approve.')}</h1></div><p class="intro-copy">${T('Öffentlich zugängliche Workflow-Demo. Änderungen gelten nur in dieser Sitzung.','Publicly accessible workflow demo. Changes last for this session only.')}</p></div><div class="editor"><nav class="editor-nav" aria-label="${T('Redaktionsbereiche','Editorial sections')}">${[['review','KI-Vorschläge','AI suggestions'],['themes','Themen & Stories','Themes & stories'],['rights','Rechte & Sensibilität','Rights & sensitivity'],['log','Freigabeprotokoll','Approval log'],['requirements','Anforderungsabgleich','Requirements coverage']].map(([v,de,en])=>`<button class="${editorTab===v?'active':''}" data-action="editor-tab" data-tab="${v}">${T(de,en)}</button>`).join('')}</nav><section>${editorContent()}</section></div></div>`}
function editorContent(){if(editorTab==='themes')return `<div class="notice">${T('Objektdaten bleiben in Daphne. Hier werden ausschließlich Themen und Begleittexte bearbeitet.','Object data remains in Daphne. Only themes and editorial copy are edited here.')}</div>${THEMES.map(t=>`<div class="callout" style="margin-bottom:18px"><h3>${esc(t.title)}</h3><label class="formfield">${T('Einleitung','Introduction')}<textarea data-theme-text="${t.id}">${esc(t.intro)}</textarea></label><div class="button-row"><button class="primary" data-action="save-theme" data-id="${t.id}">${T('Entwurf übernehmen','Apply draft')}</button><button class="secondary" data-story="${t.id}">${T('Vorschau','Preview')}</button></div></div>`).join('')}`;if(editorTab==='rights')return `<h2>${T('Anzeige nach Rechtestatus','Display by rights status')}</h2><p class="subtle" style="margin:18px 0">${T('Interaktive Fallbeispiele, keine Kennzeichnung realer Objekte. Die Kennzeichen werden im Produktivsystem ausschließlich in Daphne gepflegt.','Interactive examples, not classifications of real objects. In production, these flags are maintained only in Daphne.')}</p><label class="formfield">${T('Regelfall auswählen','Select scenario')}<select id="rights-scenario"><option value="open">CC0 / Public Domain</option><option value="by">CC BY / CC BY-SA</option><option value="protected">${T('Geschützt','Protected')}</option><option value="blocked">WEB_DUMMY2 · ${T('Digitalisat gesperrt','Image blocked')}</option><option value="neutral">${T('Sensibler Originaltitel','Sensitive original title')}</option><option value="hidden">${T('Objekt nicht zeigbar','Object excluded')}</option></select></label><div id="rights-preview">${rightsPreview('open')}</div>`;if(editorTab==='log')return `<h2>${T('Freigabeprotokoll','Approval log')}</h2><p class="subtle" style="margin:15px 0">${T('Sitzungsdaten der Demo, kein revisionssicheres Audit-Log.','Session data for this demo, not an immutable audit log.')}</p>${reviewLog.length?`<div class="table-scroll"><table><thead><tr><th>${T('Zeit','Time')}</th><th>${T('Objekt','Object')}</th><th>${T('Aktion','Action')}</th></tr></thead><tbody>${reviewLog.map(r=>`<tr><td>${r.time}</td><td>${esc(r.title)}</td><td>${esc(r.action)}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">${T('Noch keine Änderungen in dieser Sitzung.','No changes in this session yet.')}</div>`}`;if(editorTab==='requirements')return coverage();return `<div class="notice">${T('Alle Vorschläge sind ungeprüfte Textentwürfe. Freigeben verändert nur den Demostatus; es veröffentlicht keine echten Sammlungsdaten.','All suggestions are unreviewed drafts. Approval changes the demo status only; no real collection data is published.')}</div>${OBJECTS.slice(0,3).map(o=>`<article class="review-card">${objectImage(o)}<div><span class="status ${reviewState[o.id]==='approved'?'ok':''}">${reviewState[o.id]==='approved'?T('Freigegeben · Demo','Approved · demo'):reviewState[o.id]==='rejected'?T('Verworfen','Rejected'):T('Prüfung ausstehend','Awaiting review')}</span><h3>${esc(o.title)}</h3><label class="formfield" style="margin-bottom:0">${T('Vorschlag zur Bildbeschreibung','Image description draft')}<textarea id="draft-${o.id}" ${reviewState[o.id]?'readonly':''}>${esc(o.draft||o.alt)}</textarea></label><div class="chip-row" style="margin-bottom:15px">${o.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><div class="button-row"><button class="primary" data-action="approve" data-id="${o.id}" ${reviewState[o.id]?'disabled':''}>${icon('check')}${T('Freigeben','Approve')}</button><button class="secondary" data-action="reject" data-id="${o.id}" ${reviewState[o.id]?'disabled':''}>${T('Verwerfen','Reject')}</button>${reviewState[o.id]?`<button class="textbutton" data-action="reopen" data-id="${o.id}">${T('Erneut prüfen','Review again')}</button>`:''}</div></div></article>`).join('')}` }
function rightsPreview(s){const states={open:[T('Freie Nachnutzung','Open reuse'),T('Volle Anzeige, Download freigegeben, kein Wasserzeichen.','Full display, download enabled, no watermark.'),true],by:[T('Nachnutzung mit Namensnennung','Reuse with attribution'),T('Download mit Lizenzhinweis und Creditline.','Download with licence notice and credit line.'),true],protected:[T('Geschütztes Digitalisat','Protected image'),T('Nur Web-Auflösung mit Wasserzeichen. Download gesperrt; Nutzung auf Anfrage.','Web resolution with watermark. Downloads blocked; request reuse.'),false],blocked:[T('Dieses Digitalisat wird nicht angezeigt.','This image is not displayed.'),T('Bilddatei, Vorschau und Download sind gesperrt. Es wird keine Bilddatei geladen.','Image, preview and download are blocked. No image file is loaded.'),false],neutral:[T('Neutraler Objekttitel','Neutral object title'),T('Der historische Originaltitel enthält diskriminierende Sprache und wird hier nicht ausgegeben.','The historic title contains discriminatory language and is not displayed.'),false],hidden:[T('Objekt aus dem öffentlichen Bestand ausgeschlossen','Object excluded from the public collection'),T('Kein Treffer, keine Objektseite und keine Medienauslieferung im Produktivsystem.','No search result, object page or media delivery in production.'),false]};const [title,desc,download]=states[s];return `<div class="callout"><div style="height:180px;background:#e4e9df;display:grid;place-items:center;border-radius:8px;margin-bottom:20px;text-align:center;padding:20px">${s==='protected'?'<strong style="opacity:.5;transform:rotate(-15deg)">© RECHTEINHABER · DEMO</strong>':icon(s==='open'||s==='by'?'check':'bookmark')}</div><h3>${title}</h3><p>${desc}</p><button class="secondary" ${download?'data-action="demo-download"':'disabled'}>${icon('download')}${T('Download','Download')}</button></div>`}
function coverage(){return `<h2>${T('Vom Leistungsverzeichnis zum Clickdummy','From requirements to prototype')}</h2><p class="subtle" style="margin:18px 0">${T('Basis: Anforderungsregister und überarbeitete Leistungsbeschreibung. Dieser Prototyp dient der UX-Abstimmung und ist kein Abnahmenachweis.','Based on the requirements register and revised specification. This prototype supports UX review and is not an acceptance certificate.')}</p><div class="table-scroll"><table><thead><tr><th>ID</th><th>${T('Umsetzung','Implementation')}</th><th>${T('Stand','Status')}</th></tr></thead><tbody>${[['A-02, A-28','Bildgeführtes Netz, Themen, Beziehungen','Klickbar · exemplarische Kuration'],['A-31, A-32','Suche, 9 Facetten, Autocomplete, Sortierung, URL','Klickbar · 10 echte Recherchebeispiele'],['A-34, A-44','Objektansicht, Zoom, Tastatur, responsive','Klickbar · 1 Digitalisat pro Beispiel'],['A-35, A-36','Teilen, Merkliste, CSV, Druck/PDF','Browserfunktionen · kein serverseitiges Social Preview'],['A-04–06, A-19–22','DE / EN / einfache Sprache, Kontrast, Schriftgröße','Sprachentwürfe · keine BITV-Zertifizierung'],['A-07–11, A-48','KI-Freigabe und Themenredaktion','Sitzungsdemo · keine KI- oder Daphne-Anbindung'],['A-17, A-18, A-39, A-47','Rechtematrix und sensible Inhalte','Quellenlizenzen + synthetische Regelfälle'],['A-40, A-41','Nutzungsanfrage / Wissen teilen','Validierbare Formulare · kein Versand'],['A-16, A-46','eGuide / Audio','Browser-Sprachsynthese · keine MP3/OGG-Pipeline'],['A-29, A-30 (Option)','Karte / Zeitstrahl','Museumsstandorte schematisch / belegte Datierungen'],['A-50','Farben, Typografie, Logo / Kopfbereich','Design-Tokens · kein vollständiges Mandantensystem'],['A-01, A-13–15, A-23–27, A-42–43, A-45, A-49, A-51–55, B/Q','Backend, APIs, Lasttests, EU-Betrieb, Sicherheit, Abnahme','Nicht Bestandteil des Clickdummys']].map(r=>`<tr>${r.map(c=>`<td lang="de">${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="notice">${T('Offene Grundlagen: CI-Manual, Feldliste, Daphne-Testexport, Rechtematrix, geprüfte Sprachfassungen und Entscheidung zur eGuide-Variante. Chatbot, Bildsuche und Remix sind als Perspektive nicht umgesetzt.','Still needed: CI manual, field list, Daphne export, rights matrix, approved translations and eGuide decision. Future chatbot, visual search and remix capabilities are not implemented.')}</div>`}
function updateSearch(k,v){v?params.set(k,v):params.delete(k);history.replaceState({},'','?'+params);render()}
document.addEventListener('change',e=>{if(e.target.dataset.facet)updateSearch(e.target.dataset.facet,e.target.value);if(e.target.id==='sort')updateSearch('sort',e.target.value);if(e.target.id==='rights-scenario')$('#rights-preview').innerHTML=rightsPreview(e.target.value);if(e.target.id==='contrast')document.body.classList.toggle('high-contrast',e.target.checked);if(e.target.id==='motion')document.body.classList.toggle('reduced-motion',e.target.checked);if(e.target.id==='font-size')document.documentElement.style.setProperty('--scale',e.target.value)});
document.addEventListener('submit',e=>{if(e.target.id==='search-form'){e.preventDefault();updateSearch('q',$('#query').value.trim())}if(e.target.id==='contact-form'){e.preventDefault();$('#modal').innerHTML=`<div class="modal-head"><h2>${T('Anfrage durchgespielt','Request flow completed')}</h2><button class="iconbutton" data-action="close" aria-label="${T('Schließen','Close')}">${icon('close')}</button></div><div class="notice">${T('Dies war eine Simulation. Ihre Eingaben wurden weder versendet noch gespeichert.','This was a simulation. Your input was neither sent nor stored.')}</div><p>${T('Im Produktivsystem würden das zuständige Museum die Objektreferenz und Ihre Nachricht sowie Sie eine Eingangsbestätigung erhalten.','In production, the museum would receive the object reference and message, and you would receive an acknowledgement.')}</p>`}});
function persistSaved(){try{localStorage.setItem('oc-saved',JSON.stringify(saved))}catch{toast(T('Browserspeicher nicht verfügbar; Merkliste bleibt in dieser Sitzung.','Browser storage unavailable; list remains in this session.'))}}
async function shareLink(link=location.href){if(navigator.share){try{await navigator.share({title:document.title,url:link});return}catch(e){if(e.name==='AbortError')return}}try{await navigator.clipboard.writeText(link);toast(T('Link kopiert','Link copied'))}catch{modal(T('Link kopieren','Copy link'),`<label class="formfield">URL<input readonly value="${esc(link)}"></label>`)}}
function requestForm(kind){const o=currentObject();modal(kind==='knowledge'?T('Wissen teilen','Share knowledge'):T('Nutzung anfragen','Request image reuse'),`<p><strong>${esc(o.title)}</strong><br><span class="subtle">${o.id} · ${esc(o.museum)}</span></p><p class="hint">${T('Demoformular: Es erfolgt kein Versand. Bitte nur Testdaten eingeben.','Demo form: nothing will be sent. Please enter test data only.')}</p><form id="contact-form"><label class="formfield">${T('Name','Name')}<input name="name" required autocomplete="off"></label><label class="formfield">${T('E-Mail','Email')}<input name="email" type="email" required autocomplete="off"></label>${kind==='request'?`<label class="formfield">${T('Verwendungszweck','Intended use')}<select required><option value="">${T('Bitte wählen','Please choose')}</option><option>${T('Forschung / Publikation','Research / publication')}</option><option>${T('Bildung / Unterricht','Education')}</option><option>${T('Private Nutzung','Personal use')}</option><option>${T('Andere Nutzung','Other use')}</option></select></label>`:''}<label class="formfield">${kind==='knowledge'?T('Ihr Hinweis','Your contribution'):T('Ihre Nachricht','Your message')}<textarea required minlength="10" maxlength="3000"></textarea></label><label class="checkrow"><input type="checkbox" required> <span>${T('Ich habe verstanden, dass dies eine Simulation ist.','I understand that this is a simulation.')}</span></label><button class="primary" style="margin-top:20px">${T('Anfrage simulieren','Simulate request')}</button></form>`)}
let zoom=1,zoomMode='whole';
function openZoom(){const o=currentObject(),m=$('#modal');zoom=1;zoomMode='whole';m.className='zoom-dialog';m.innerHTML=`<div class="modal-head"><h2>${esc(o.title)}</h2><button class="iconbutton" data-action="close" aria-label="${T('Schließen','Close')}">${icon('close')}</button></div><div class="zoom-area" tabindex="0" aria-label="${T('Bildbereich, mit Pfeiltasten scrollbar','Image area, scroll with arrow keys')}"><img id="zoom-image" src="${esc(o.imageUrl)}" alt="${esc(o.alt)}" style="width:700px;max-width:100%;"></div><div class="zoom-actions"><button class="iconbutton" data-action="zoom-minus" aria-label="${T('Verkleinern','Zoom out')}">${icon('minus')}</button><span id="zoom-level">100 %</span><button class="iconbutton" data-action="zoom-plus" aria-label="${T('Vergrößern','Zoom in')}">${icon('plus')}</button><button class="iconbutton" data-action="zoom-reset" aria-label="${T('Ansicht zurücksetzen','Reset view')}">${icon('reset')}</button><button class="secondary" data-action="zoom-crop">${T('Detailausschnitt','Detail crop')}</button></div><p class="subtle" style="text-align:center;color:#b6c5cb">${T('Eine Aufnahme · Gesamtansicht und Ausschnitt','One photograph · full image and crop')}</p>`;m.showModal()}
function actionFull(a,b){if(a==='save'){const id=b.dataset.id;saved=saved.includes(id)?saved.filter(i=>i!==id):[...saved,id];persistSaved();const scroll=window.scrollY;render();window.scrollTo(0,scroll);toast(saved.includes(id)?T('In Ihrer Merkliste gespeichert','Saved to your list'):T('Aus der Merkliste entfernt','Removed from your list'))}else if(a==='detail-tab'){detailTab=b.dataset.tab;$$('.tabs button').forEach(x=>{x.classList.toggle('active',x.dataset.tab===detailTab);x.setAttribute('aria-selected',String(x.dataset.tab===detailTab))});$('#detail-content').innerHTML=detailContent(currentObject())}else if(a==='share')shareLink();else if(a==='like'){b.classList.toggle('saved');b.setAttribute('aria-pressed',b.classList.contains('saved'));toast(T('Gefällt mir · nur lokale Demo, keine öffentliche Zählung','Like · local demo only, no public counter'))}else if(a==='reset-search')go('search');else if(a==='remove-filter')updateSearch(b.dataset.key,'');else if(a==='filters')$('#filters').classList.toggle('open');else if(a==='layout')updateSearch('layout',params.get('layout')==='list'?'grid':'list');else if(a==='request'||a==='knowledge')requestForm(a);else if(a==='zoom')openZoom();else if(a.startsWith('zoom-')){if(a==='zoom-crop'){zoomMode=zoomMode==='whole'?'crop':'whole';zoom=zoomMode==='crop'?2:1;b.textContent=zoomMode==='crop'?T('Gesamtansicht','Full image'):T('Detailausschnitt','Detail crop')}else zoom=a==='zoom-reset'?1:Math.max(.5,Math.min(4,zoom+(a==='zoom-plus'?.25:-.25)));$('#zoom-image').style.width=700*zoom+'px';$('#zoom-image').style.maxWidth=zoom<=1?'100%':'none';$('#zoom-level').textContent=Math.round(zoom*100)+' %'}else if(a==='image-description')modal(T('Bildbeschreibung','Image description'),`<p lang="de">${esc(currentObject().alt)}</p><p class="hint">${T('Beschreibung für den Prototyp. Eine redaktionelle Freigabe des Museums steht aus.','Prototype description. Museum editorial approval is pending.')}</p>`);else if(a==='speak'){if(!('speechSynthesis'in window)){toast(T('Vorlesen wird von diesem Browser nicht unterstützt.','Speech is unavailable in this browser.'));return}speechSynthesis.cancel();let s=new SpeechSynthesisUtterance(lang==='easy'?currentObject().easy:currentObject().description);s.lang='de-DE';s.rate=.9;speechSynthesis.speak(s);toast(T('Deutscher Objekttext wird vorgelesen','Reading the German object text'))}else if(a==='stop-speak'){if('speechSynthesis'in window)speechSynthesis.cancel()}else if(a==='older'||a==='younger'){const o=currentObject(),same=OBJECTS.filter(x=>x.id!==o.id&&x.year&&x.tags.some(t=>o.tags.includes(t))&&(a==='older'?x.year<(o.year||9999):x.year>(o.year||0))).sort((x,y)=>Math.abs(x.year-(o.year||0))-Math.abs(y.year-(o.year||0)));if(same.length)go('object',{id:same[0].id});else toast(T('Kein passendes datiertes Objekt in den Beispieldaten.','No matching dated object in the sample data.'))}else if(a==='save-story'){const t=THEMES.find(x=>x.id===b.dataset.id);saved=[...new Set([...saved,...t.ids.map(i=>OBJECTS[i].id)])];persistSaved();chrome();toast(T('Objekte zur Merkliste hinzugefügt','Objects added to your list'))}else if(a==='share-saved'){const ids=params.get('ids')||saved.join(',');shareLink(location.origin+location.pathname+url('saved',{ids}))}else if(a==='import-saved'){saved=[...new Set([...saved,...(params.get('ids')||'').split(',').filter(id=>OBJECTS.some(o=>o.id===id))])];persistSaved();go('saved')}else if(a==='csv'){const ids=params.get('ids')?.split(',')||saved;const rows=[['ID','Titel','Person','Datierung','Museum','Lizenz','Credit','Quelle'],...OBJECTS.filter(o=>ids.includes(o.id)).map(o=>[o.id,o.title,o.person,o.date,o.museum,o.license,o.credit,o.sourceUrl])];download(new Blob(['\ufeff'+rows.map(r=>r.map(c=>'"'+String(c).replace(/"/g,'""')+'"').join(';')).join('\r\n')],{type:'text/csv;charset=utf-8;'}),'Meine-Merkliste.csv')}else if(a==='print')window.print();else if(a==='map-select'){mapSelected=b.dataset.id;$('#exploration').innerHTML=mapView()}else if(a==='editor-tab'){editorTab=b.dataset.tab;render()}else if(a==='approve'||a==='reject'){const o=OBJECTS.find(o=>o.id===b.dataset.id);o.draft=$('#draft-'+o.id).value;reviewState[o.id]=a==='approve'?'approved':'rejected';reviewLog.unshift({time:new Date().toLocaleTimeString(),title:o.title,action:a==='approve'?'Freigegeben (Demo)':'Verworfen (Demo)'});render();toast(T('Demostatus aktualisiert · keine Veröffentlichung','Demo status updated · nothing published'))}else if(a==='reopen'){delete reviewState[b.dataset.id];render()}else if(a==='save-theme'){const t=THEMES.find(x=>x.id===b.dataset.id);t.intro=$(`[data-theme-text="${t.id}"]`).value;reviewLog.unshift({time:new Date().toLocaleTimeString(),title:t.title,action:'Themenentwurf geändert (Demo)'});toast(T('Entwurf für diese Sitzung übernommen','Draft updated for this session'))}else if(a==='demo-download')toast(T('Regelfall demonstriert. Echte Downloads finden Sie auf den Objektseiten.','Scenario demonstrated. Real downloads are available on object pages.'));else if(a==='access')modal(T('So passt die Sammlung zu Ihnen.','Make the collection work for you.'),`<label class="formfield">${T('Schriftgröße','Text size')}<select id="font-size"><option value="1">100 %</option><option value="1.25">125 %</option><option value="1.5">150 %</option><option value="2">200 %</option></select></label><label class="checkrow"><input id="contrast" type="checkbox" ${document.body.classList.contains('high-contrast')?'checked':''}>${T('Erhöhter Kontrast','Higher contrast')}</label><label class="checkrow"><input id="motion" type="checkbox" ${document.body.classList.contains('reduced-motion')?'checked':''}>${T('Bewegung reduzieren','Reduce motion')}</label><p>${T('Alle Objekte im Netz sind auch per Tabulatortaste erreichbar. Enter öffnet ein Objekt, Escape schließt Dialoge. Die Listenansicht bietet dieselben Inhalte ohne räumliches Netz.','Use Tab to navigate network objects, Enter to open and Escape to close dialogs. The list view provides the same content without spatial navigation.')}</p><p class="hint">${T('Noch keine unabhängige BITV-Prüfung. Leichte-Sprache-Texte sind ungeprüfte Entwürfe.','Not independently BITV audited. Easy-language texts are unreviewed drafts.')}</p>`);else if(a==='sources')modal(T('Bilder mit Herkunft.','Images with provenance.'),`<p>${T('Alle Bilder stammen aus Wikimedia Commons. Für die Vorschau wurden sie verkleinert. Lizenzen gelten jeweils für die verlinkte Datei.','All images are from Wikimedia Commons and were resized for this preview. Each licence applies to its linked file.')}</p>${OBJECTS.map(o=>`<div class="source-item"><a href="${esc(o.sourceUrl)}" target="_blank" rel="noopener">${esc(o.title)}</a><small>${esc(o.credit)} · <a href="${esc(o.licenseUrl)}" target="_blank" rel="noopener">${esc(o.license)}</a></small></div>`).join('')}`);else if(a==='privacy')modal(T('Datenschutz & Kontakt','Privacy & contact'),`<p>${T('Dieser Clickdummy versendet keine Nachrichten und führt kein Besuchertracking aus. Merklisten bleiben im lokalen Browserspeicher. Geteilte Links enthalten nur die ausgewählten Objekt-IDs.','This prototype sends no messages and has no visitor analytics. Saved objects remain in browser storage. Shared links contain only selected object IDs.')}</p><p>${T('Bilddateien werden mit der Seite bereitgestellt. Die Vorschau lädt Schriftarten von Google Fonts. Für den späteren EU-Produktivbetrieb sind lokal gehostete Schriften und geprüfte Rechtstexte vorgesehen.','Images are served with the site. This preview loads fonts from Google Fonts. Production requires locally hosted fonts and approved legal notices.')}</p><p><a href="https://luebecker-museen.de/" target="_blank" rel="noopener">${T('Offizielle Website der Lübecker Museen','Official Lübeck Museums website')}</a></p><p class="hint">${T('Gestaltungsvorschlag, kein offizieller Internetauftritt der Museen.','Design proposal, not the official museum website.')}</p>`);else if(a==='about')modal(T('Ein Prototyp zum Entdecken und Prüfen','A prototype for exploration and review'),`<p>${T('Der Clickdummy übersetzt das Anforderungsregister und das überarbeitete Pflichtenheft in erlebbare Nutzerwege. Er verwendet zehn recherchierte Objekte mit Quellen- und Lizenzhinweisen.','This clickdummy translates the requirements register and revised specification into interactive user journeys. It uses ten researched objects with sources and licence details.')}</p><p>${T('Klickbar: Sammlungsnetz, Suche, neun Filter, Objektseiten, Bildzoom, Themen, Merkliste, CSV-Export, Druck/PDF und Freigabe-Demo.','Interactive: network, search, nine filters, object pages, image zoom, stories, bookmarks, CSV export, print/PDF and editorial approval demo.')}</p><p>${T('Simuliert: KI-Freigabe, Kontaktversand, Rechteszenarien. Nicht angebunden: Daphne, OAI-PMH, Produktions-API, professionelle Audios, Konten und Medienpipeline.','Simulated: AI approval, contact submission and rights scenarios. Not connected: Daphne, OAI-PMH, production APIs, professional audio, accounts or media pipeline.')}</p><p>${T('Das CI-Manual fehlt. Typografie, Farben und Wortmarke sind ein vorläufiger Gestaltungsvorschlag. KERN-inspirierte native Formulare; keine behauptete KERN-Konformität.','The CI manual was not supplied. Typography, colours and wordmark are provisional. Native forms inspired by KERN; no claim of KERN compliance.')}</p><button class="primary" data-action="open-coverage">${T('Anforderungsabgleich öffnen','Open requirements coverage')}</button>`);else if(a==='open-coverage'){$('#modal').close();editorTab='requirements';go('editor')}}
function download(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close()});
document.addEventListener('keydown',e=>{if(e.target.matches('.tabs [role="tab"]')&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const tabs=$$('.tabs [role="tab"]');let i=tabs.indexOf(e.target);i=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[i].focus();tabs[i].click()}});
const originalGo=go;go=function(page,extra){if($('#modal').open)$('#modal').close();if('speechSynthesis'in window)speechSynthesis.cancel();if(page==='object')detailTab='overview';originalGo(page,extra)};
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'search_collection',description:'Navigate to collection results for a text query in the visible prototype.',inputSchema:{type:'object',properties:{query:{type:'string',maxLength:200}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:false},execute:({query})=>{if(typeof query!=='string'||query.length>200)throw Error('Query must be a string of up to 200 characters');go('search',{q:query});return {count:filtered().length,objects:filtered().map(o=>({id:o.id,title:o.title}))}}})}catch{}}
render();
